(function(){'use strict';const state={session:null,scene:'studio',frame:null,ready:false,view:'front',framing:'full',motion:'idle',version:'new',lighting:'live'};const $=s=>document.querySelector(s),status=s=>{$('#entry-status').textContent=s;};
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(body&&state.session?.csrf?{'X-City-CSRF':state.session.csrf}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'REQUEST_FAILED'),{code:d.error});return d;}
function errorText(e){return({PLAY_EMPLOYEE_FORMAT:'請輸入自己的7碼員編。',PLAY_EMPLOYEE_UNAVAILABLE:'這個員編不在本次三人試作名單，請確認本人員編。',PLAY_LOGIN_RATE_LIMIT:'登入次數較多，請稍等一分鐘。',PLAY_SIGN_OUT_FIRST:'請先按「切換員編」，再登入另一位試作角色。',PREVIEW_EXPIRED:'臨時試作已到期，請向主管索取後續入口。'}[e.code]||'目前無法完成，請稍後再試。原城市角色不受影響。');}
function send(action,value){if(state.ready&&state.frame)state.frame.contentWindow.postMessage({type:'avatar-artlab/control',action,value},location.origin);}
function sync(){for(const k of['version','framing','view','motion'])send(k,state[k]);if(state.scene==='game')send('lighting',state.lighting);}
function scene(){state.ready=false;$('#frame-mount').replaceChildren();const f=document.createElement('iframe');f.title=state.scene==='studio'?'本人3D造型':'本人城市試作';f.src=state.scene==='studio'?'studio.html':'game.html';$('#frame-mount').append(f);state.frame=f;for(const b of document.querySelectorAll('[data-scene]'))b.setAttribute('aria-pressed',String(b.dataset.scene===state.scene));$('#preview-status').textContent='正在載入你的造型…';}
function render(){const active=!!state.session?.profile;$('#entry-card').hidden=active;$('#trial-area').hidden=!active;if(!active)return;$('#person-name').textContent=state.session.profile.nickname;$('#person-id').textContent=state.session.playLogin?.employeeIdMasked||'';$('#scene-title').textContent=state.session.profile.nickname+'的造型試作';}
async function login(event){event?.preventDefault();const id=$('#employee-id').value.trim();if(!/^\d{7}$/.test(id)){status('請輸入自己的7碼員編。');return;}$('#employee-submit').disabled=true;status('正在讀取本人的試作造型…');try{state.session=await api('play-login',{employeeId:id});$('#employee-id').value='';render();scene();}catch(e){status(errorText(e));}finally{$('#employee-submit').disabled=false;}}
$('#employee-form').addEventListener('submit',login);$('#switch-person').onclick=async()=>{try{await api('logout',{});}catch{}state.frame?.remove();state.frame=null;state.session=null;state.ready=false;render();status('輸入本人員編查看造型。');};
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.scene){state.scene=button.dataset.scene;scene();return;}const action=button.dataset.action,value=button.dataset.value;if(!['version','framing','view','motion','lighting'].includes(action))return;state[action]=value;for(const b of document.querySelectorAll('[data-action="'+action+'"]'))b.setAttribute('aria-pressed',String(b.dataset.value===value));send(action,value);});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==state.frame?.contentWindow)return;if(e.data?.type==='avatar-artlab/ready'){state.ready=true;$('#preview-status').textContent='可拖曳旋轉，或進入城市看本人造型。';sync();}if(e.data?.type==='avatar-artlab/expired'){$('#preview-status').textContent='試作登入已到期，請按「切換員編」重新登入。';}});
api('session').then(d=>{if(!d.playLogin||!/^portrait-trial-[abc]-v1$/.test(d.profile?.avatarPreset||''))return;state.session=d;render();scene();}).catch(()=>{});render();window.ThreePeopleTrial=Object.freeze({state,api});
})();
